if isinstance(d,dict): print(d.get("message"))
else:
  for x in d: print(x["tag_name"],x["published_at"],x["prerelease"])'; GIT_TERMINAL_PROMPT=0 git ls-remote --tags https://github.com/$r 2>&1 | grep -E 'refs/tags/v([1-9]|[1-9][0-9])(\.[0-9]+\.[0-9]+)?(\^\{\})?$|fatal' | sort -t/ -k3 -V | tail -8; done

